public class Main {
    public static void main(String[] args) {
        Akun a = new Akun("Budi", 100000);
        System.out.println(a.getNama());
        System.out.println(a.getSaldo());
        a.tampilkanInfo();
    }
}

class Akun {
    private String nama;
    private int saldo;

    Akun(String nama, int saldo) {
        this.nama = nama;
        this.saldo = saldo;
    }

    public String getNama() {
        return nama;
    }

    public int getSaldo() {
        return saldo;
    }

    void tampilkanInfo() {
        System.out.println(nama + " memiliki saldo " + saldo);
    }
}

